import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.2
.target sm_89
.address_size 64

.visible .entry conv_transpose3d_kernel(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 total,
    .param .u32 has_bias
)
{
    .reg .pred %p_oob, %p_ci, %p_kz, %p_ky, %p_kx;
    .reg .pred %p_zlo, %p_zhi, %p_ylo, %p_yhi, %p_xlo, %p_xhi;
    .reg .pred %p_nobias;
    .reg .u64 %rd_in, %rd_w, %rd_b, %rd_out;
    .reg .u64 %rd_addr, %rd_waddr, %rd_baddr, %rd_oaddr;
    .reg .u64 %rd_off, %rd_woff, %rd_boff, %rd_ooff;
    .reg .u32 %r_total, %r_hasb, %r_tid, %r_t;
    .reg .u32 %r_ctaid, %r_ntid, %r_tidx;
    .reg .u32 %r_ox, %r_oy, %r_oz, %r_co, %r_n;
    .reg .u32 %r_ci, %r_kz, %r_ky, %r_kx;
    .reg .u32 %r_nci, %r_in_ci_base, %r_w_ci_base;
    .reg .u32 %r_iz, %r_iy, %r_ix;
    .reg .u32 %r_elem, %r_welem;
    .reg .u32 %r_tmp0, %r_tmp1;
    .reg .s32 %s_oz, %s_oy, %s_ox, %s_kz, %s_ky, %s_kx;
    .reg .s32 %s_iz, %s_iy, %s_ix;
    .reg .f32 %f_acc, %f_x, %f_w, %f_b;

    ld.param.u64 %rd_in, [in_ptr];
    ld.param.u64 %rd_w, [w_ptr];
    ld.param.u64 %rd_b, [b_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.u32 %r_total, [total];
    ld.param.u32 %r_hasb, [has_bias];

    mov.u32 %r_ctaid, %ctaid.x;
    mov.u32 %r_ntid, %ntid.x;
    mov.u32 %r_tidx, %tid.x;
    mad.lo.u32 %r_tid, %r_ctaid, %r_ntid, %r_tidx;
    setp.ge.u32 %p_oob, %r_tid, %r_total;
    @%p_oob bra EXIT;

    mov.u32 %r_t, %r_tid;
    rem.u32 %r_ox, %r_t, 98;
    div.u32 %r_t, %r_t, 98;
    rem.u32 %r_oy, %r_t, 98;
    div.u32 %r_t, %r_t, 98;
    rem.u32 %r_oz, %r_t, 98;
    div.u32 %r_t, %r_t, 98;
    rem.u32 %r_co, %r_t, 24;
    div.u32 %r_n, %r_t, 24;

    cvt.s32.u32 %s_oz, %r_oz;
    cvt.s32.u32 %s_oy, %r_oy;
    cvt.s32.u32 %s_ox, %r_ox;

    mov.f32 %f_acc, 0f00000000;
    mov.u32 %r_ci, 0;

CI_LOOP:
    setp.lt.u32 %p_ci, %r_ci, 48;
    @!%p_ci bra CI_DONE;

    mul.lo.u32 %r_nci, %r_n, 48;
    add.u32 %r_nci, %r_nci, %r_ci;
    mul.lo.u32 %r_in_ci_base, %r_nci, 96;

    mul.lo.u32 %r_w_ci_base, %r_ci, 24;
    add.u32 %r_w_ci_base, %r_w_ci_base, %r_co;
    mul.lo.u32 %r_w_ci_base, %r_w_ci_base, 27;

    mov.u32 %r_kz, 0;
KZ_LOOP:
    setp.lt.u32 %p_kz, %r_kz, 3;
    @!%p_kz bra KZ_DONE;
    cvt.s32.u32 %s_kz, %r_kz;
    sub.s32 %s_iz, %s_oz, %s_kz;
    setp.ge.s32 %p_zlo, %s_iz, 0;
    @!%p_zlo bra KZ_NEXT;
    setp.lt.s32 %p_zhi, %s_iz, 96;
    @!%p_zhi bra KZ_NEXT;
    cvt.u32.s32 %r_iz, %s_iz;

    mov.u32 %r_ky, 0;
KY_LOOP:
    setp.lt.u32 %p_ky, %r_ky, 3;
    @!%p_ky bra KY_DONE;
    cvt.s32.u32 %s_ky, %r_ky;
    sub.s32 %s_iy, %s_oy, %s_ky;
    setp.ge.s32 %p_ylo, %s_iy, 0;
    @!%p_ylo bra KY_NEXT;
    setp.lt.s32 %p_yhi, %s_iy, 96;
    @!%p_yhi bra KY_NEXT;
    cvt.u32.s32 %r_iy, %s_iy;

    mov.u32 %r_kx, 0;
KX_LOOP:
    setp.lt.u32 %p_kx, %r_kx, 3;
    @!%p_kx bra KX_DONE;
    cvt.s32.u32 %s_kx, %r_kx;
    sub.s32 %s_ix, %s_ox, %s_kx;
    setp.ge.s32 %p_xlo, %s_ix, 0;
    @!%p_xlo bra KX_NEXT;
    setp.lt.s32 %p_xhi, %s_ix, 96;
    @!%p_xhi bra KX_NEXT;
    cvt.u32.s32 %r_ix, %s_ix;

    add.u32 %r_elem, %r_in_ci_base, %r_iz;
    mul.lo.u32 %r_elem, %r_elem, 96;
    add.u32 %r_elem, %r_elem, %r_iy;
    mul.lo.u32 %r_elem, %r_elem, 96;
    add.u32 %r_elem, %r_elem, %r_ix;
    mul.wide.u32 %rd_off, %r_elem, 4;
    add.u64 %rd_addr, %rd_in, %rd_off;
    ld.global.f32 %f_x, [%rd_addr];

    mul.lo.u32 %r_welem, %r_kz, 9;
    mul.lo.u32 %r_tmp0, %r_ky, 3;
    add.u32 %r_welem, %r_welem, %r_tmp0;
    add.u32 %r_welem, %r_welem, %r_kx;
    add.u32 %r_welem, %r_welem, %r_w_ci_base;
    mul.wide.u32 %rd_woff, %r_welem, 4;
    add.u64 %rd_waddr, %rd_w, %rd_woff;
    ld.global.f32 %f_w, [%rd_waddr];

    fma.rn.f32 %f_acc, %f_x, %f_w, %f_acc;

KX_NEXT:
    add.u32 %r_kx, %r_kx, 1;
    bra KX_LOOP;
KX_DONE:
KY_NEXT:
    add.u32 %r_ky, %r_ky, 1;
    bra KY_LOOP;
KY_DONE:
KZ_NEXT:
    add.u32 %r_kz, %r_kz, 1;
    bra KZ_LOOP;
KZ_DONE:
    add.u32 %r_ci, %r_ci, 1;
    bra CI_LOOP;
CI_DONE:

    setp.eq.u32 %p_nobias, %r_hasb, 0;
    @%p_nobias bra STORE;
    mul.wide.u32 %rd_boff, %r_co, 4;
    add.u64 %rd_baddr, %rd_b, %rd_boff;
    ld.global.f32 %f_b, [%rd_baddr];
    add.f32 %f_acc, %f_acc, %f_b;

STORE:
    mul.wide.u32 %rd_ooff, %r_tid, 4;
    add.u64 %rd_oaddr, %rd_out, %rd_ooff;
    st.global.f32 [%rd_oaddr], %f_acc;

EXIT:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0,
                 dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if in_channels % groups != 0:
            raise ValueError("in_channels must be divisible by groups")
        if out_channels % groups != 0:
            raise ValueError("out_channels must be divisible by groups")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups

        self.conv_transpose3d = nn.Module()
        self.conv_transpose3d.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        )
        if bias:
            self.conv_transpose3d.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.conv_transpose3d.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()
        n, cin, d, h, w = x.shape
        out_d = (d - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + self.output_padding + 1
        out_h = (h - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + self.output_padding + 1
        out_w = (w - 1) * self.stride - 2 * self.padding + self.dilation * (self.kernel_size - 1) + self.output_padding + 1
        out = torch.empty((n, self.out_channels, out_d, out_h, out_w), device=x.device, dtype=x.dtype)

        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        has_bias = 1 if bias is not None else 0
        bias_arg = bias if bias is not None else out

        total = out.numel()
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module.launch(
            "conv_transpose3d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, weight, bias_arg, out, i32(total), i32(has_bias)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

